#!/usr/bin/env python3
"""Build OptLevi's minimal Bedrock JSON-UI pack, without copying vanilla UI files."""
import argparse
import json
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "resources" / "levi_api"
# Reuse the user's icon generated by the existing OptLevi preparation step.
DEFAULT_ICON = ROOT / "ModMenuBE" / "assets" / "icon.png"
OUTPUT = ROOT / "build" / "OptLevi-LeviAPI-0.2.0.mcpack"

def build(output=OUTPUT, icon=DEFAULT_ICON):
    output.parent.mkdir(parents=True, exist_ok=True)
    for f in ("manifest.json", "ui/_ui_defs.json", "ui/start_screen.json", "ui/pause_screen.json", "texts/languages.json"):
        json.loads((SOURCE / f).read_text(encoding="utf-8"))
    ui = json.loads((SOURCE / "ui/start_screen.json").read_text(encoding="utf-8"))
    button = ui["optlevi_menu_button@common_buttons.light_text_form_fitting_button"]
    assert button["$pressed_button_name"] == "button.optlevi_open_menu"
    assert icon.is_file(), "OptLevi icon missing: run prepare-optlevi.py first"
    assert icon.read_bytes().startswith(bytes((137, 80, 78, 71, 13, 10, 26, 10)))
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for p in sorted(SOURCE.rglob("*")):
            if p.is_file():
                z.write(p, p.relative_to(SOURCE).as_posix())
        z.write(icon, "pack_icon.png")
    print(f"Resource pack ready: {output}")

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=OUTPUT)
    parser.add_argument("--icon", type=Path, default=DEFAULT_ICON)
    args = parser.parse_args()
    build(args.output, args.icon)
